event.content:
{
  "name": "ticket_open",
  "description": "Open a new ticket",
  "arguments": {
    "type": "object",
    "properties": {
      "client": {
        "description": "Client used for this ticket",
        "type": "string"
      },
      "draft": {
        "description": "Optional draft slug to seed ticket workspace",
        "type": "string"
      },
      "goal": {
        "description": "Goal ID",
        "type": "string"
      },
      "issue": {
        "description": "Link to existing GitHub issue URL instead of creating new one",
        "type": "string"
      },
      "llm": {
        "description": "LLM used for this ticket",
        "type": "string"
      },
      "no-issue": {
        "description": "Skip GitHub issue creation",
        "type": "boolean"
      },
      "no_github": {
        "description": "Skip GitHub issue creation",
        "type": "boolean"
      },
      "parent": {
        "description": "Parent ticket slug for nested tickets",
        "type": "string"
      },
      "prompt": {
        "description": "Ticket prompt/description",
        "type": "string"
      },
      "title": {
        "description": "Ticket title",
        "type": "string"
      }
    },
    "required": []
  }
}
